/**
 * @typedef {string|((input: string, importer: string) => string|false|Promise<string|false>)|false} Alias
 */
/**
 * @typedef {{ [key: string]: Alias }} AliasMap
 */
/**
 * Escape RegExp modifiers in a string.
 * @param {string} source
 */
export function escapeRegexBody(source: string): string;
/**
 * Create a regex for alias match.
 * @param {string} entry
 * @param {ALIAS_MODE} [mode]
 */
export function createAliasRegex(entry: string, mode?: number | undefined): RegExp;
/**
 * Create a regex for multiple aliases match.
 * @param {string[]} entries
 * @param {ALIAS_MODE} [mode]
 */
export function createAliasesRegex(entries: string[], mode?: number | undefined): RegExp;
/**
 * Extract a list of mapped modules from an alias map.
 * @param {AliasMap} aliasMap
 * @param {string[]} external
 */
export function getMappedModules(aliasMap: AliasMap, external?: string[]): string[];
/**
 * Extract a list of empty modules from an alias map.
 * @param {AliasMap} aliasMap
 * @param {string[]} external
 */
export function getEmptyModules(aliasMap: AliasMap, external?: string[]): string[];
/**
 * Create a map of regex/resolutions for an alias map.
 * @param {AliasMap} aliasMap
 * @param {ALIAS_MODE} [mode]
 */
export function createAliasRegexexMap(aliasMap: AliasMap, mode?: number | undefined): Map<RegExp, {
    key: string;
    value: Alias;
}>;
/**
 * Create a regex for empty modules.
 * @param {AliasMap} aliasMap
 * @param {ALIAS_MODE} [mode]
 */
export function createEmptyRegex(aliasMap: AliasMap, mode?: number | undefined): RegExp;
export type ALIAS_MODE = number;
export namespace ALIAS_MODE {
    const ANY: number;
    const START: number;
    const FULL: number;
}
export type Alias = string | false | ((input: string, importer: string) => string | false | Promise<string | false>);
export type AliasMap = {
    [key: string]: Alias;
};
